SELECT DISTINCT d.id, d.n_created_at FROM (SELECT `n`.`id`, `n`.`client_id`, `n`.`batch_id`, `n`.`user_id`, `n`.`template_id`, `n`.`template_version`, `n`.`channel`, `n`.`category`, `n`.`status`, `n`.`recipient_email`, `n`.`variables`, `n`.`rendered_title`, `n`.`rendered_body`, `n`.`rendered_text`, `n`.`rendered_data`, `n`.`attempt_count`, `n`.`lease_until`, `n`.`provider_message_id`, `n`.`last_error_code`, `n`.`queued_at`, `n`.`sent_at`, `n`.`delivered_at`, `n`.`read_at`, `n`.`created_at` AS n_created_at, `n`.`updated_at`, `t`.`id` AS t_id, `t`.`key`, `t`.`html_body` FROM `notification` `n` INNER JOIN `template` `t` ON `t`.`id`=`n`.`template_id` AND (`t`.`deleted_at` IS NULL) WHERE `n`.`created_at` >= '2026-10-03 00:00:00' AND `n`.`created_at` < '2026-10-10 00:00:00') d ORDER BY d.n_created_at DESC, d.id DESC LIMIT 51;
